{"code": "import tensorflow as tf
import os

# Function to check if file is a valid image using TensorFlow
def is_valid_tf_image(file_path):
    try:
        # Try to read and decode the file
        img_bytes = tf.io.read_file(file_path)
        img = tf.image.decode_image(img_bytes, channels=3, expand_animations=False)
        # If we get here, the file is valid
        return True, file_path
    except:
        return False, file_path

# Test the files we have
corrupted_files = []
valid_files = []

data_dir = 'data_small/chest-xray-pneumonia/chest_xray/train'
classes = ['NORMAL', 'PNEUMONIA']

total_checked = 0
for class_name in classes:
    class_dir = os.path.join(data_dir, class_name)
    img_extensions = {'.jpeg', '.jpg', '.png', '.bmp', '.gif', '.tiff'}

    for filename in os.listdir(class_dir):
        if os.path.splitext(filename)[1].lower() in img_extensions:
            file_path = os.path.join(class_dir, filename)
            total_checked += 1
            try:
                img_bytes = tf.io.read_file(file_path)
                img = tf.image.decode_image(img_bytes, channels=3, expand_animations=False)
                valid_files.append(file_path)
            except Exception as e:
                corrupted_files.append((file_path, str(e)))

print(f"Checked {total_checked} files")
print(f"Valid: {len(valid_files)}, Corrupted: {len(corrupted_files)}")
print("\nFirst 10 corrupted files:")
for f, err in corrupted_files[:10]:
    print(f"  {os.path.basename(f)}: {err}")"}

